import math
import pathlib
import tempfile
import threading
from app import Queue

with tempfile.TemporaryDirectory() as td:
    path = pathlib.Path(td) / 'q.db'
    q1, q2 = Queue(path), Queue(path)

    payload = {'nested': [1, None, {'ok': True}]}
    q1.put('first', payload)
    payload['nested'][2]['ok'] = False
    first = q2.claim('same-worker', 0, 5)
    assert set(first) == {'payload', 'expires_at', 'receipt'}
    assert first['payload'] == {'nested': [1, None, {'ok': True}]}
    first['payload']['nested'].clear()
    assert q1.claim('other', 4.999, 2) is None
    second = q1.claim('same-worker', 5, 2)
    assert second['expires_at'] == 7
    assert q2.ack(first['receipt'], 5) is False
    assert q2.ack(second['receipt'], 5) is True
    assert q1.ack(second['receipt'], 5) is False
    try:
        q1.put('first', 'duplicate-after-done')
    except ValueError:
        pass
    else:
        raise AssertionError('completed IDs must remain unique')

    for bad in (True, False, 0, -1, float('inf'), float('-inf'), float('nan')):
        try:
            q1.claim('worker', 6, bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f'invalid lease accepted: {bad"'!r}'"')

    for bad_payload in ({'nan': math.nan}, {'inf': math.inf}, {1, 2}, object()):
        try:
            q1.put('bad-' + str(len(str(bad_payload))), bad_payload)
        except (TypeError, ValueError, RecursionError):
            pass
        else:
            raise AssertionError(f'unsupported payload accepted: {bad_payload"'!r}'"')
    too_deep = None
    for _ in range(1100):
        too_deep = [too_deep]
    try:
        q1.put('too-deep', too_deep)
    except RecursionError:
        pass
    else:
        raise AssertionError('excessive JSON nesting accepted')
    q1.put('after-errors', {'still': 'usable'})
    assert q2.claim('worker', 8, 1)['payload'] == {'still': 'usable'}

with tempfile.TemporaryDirectory() as td:
    path = pathlib.Path(td) / 'race.db'
    q1, q2 = Queue(path), Queue(path)
    q1.put('only', 1)
    barrier = threading.Barrier(3)
    results = []
    def claim(q, worker):
        barrier.wait()
        results.append(q.claim(worker, 0, 10))
    threads = [threading.Thread(target=claim, args=(q1, 'a')),
               threading.Thread(target=claim, args=(q2, 'b'))]
    for t in threads: t.start()
    barrier.wait()
    for t in threads: t.join()
    assert sum(result is not None for result in results) == 1, results
print('contract checks passed')
